 void SelectWorkspace(string key){if(workspaceBusy||workspaceForms.Any(WorkspaceFormBusy)){status.Text="请先等待当前设置应用完成。";return;}EnsureWorkspaceForm(key);if(key=="deployment")RefreshNativeSteps();workspaceBody.SuspendLayout();workspaceBody.Controls.Clear();workspaceBody.AutoScrollPosition=Point.Empty;var page=workspacePages[key];workspaceBody.Controls.Add(page);page.Location=new Point(24,6);workspacePage=key;foreach(var pair in workspaceNav){pair.Value.BackColor=pair.Key==key?Color.FromArgb(53,83,83):StudioUi.Rail;pair.Value.ForeColor=pair.Key==key?Color.FromArgb(247,252,250):Color.FromArgb(197,215,217);pair.Value.Font=new Font(Font, pair.Key==key?FontStyle.Bold:FontStyle.Regular);}workspaceTitle.Text=workspaceNav[key].Text;workspaceGuide.Text=GuideSummary(key);workspaceSubtitle.Text=key=="palette"?"编辑基础底色与双方气泡 · 已连接预览时可直接应用":key=="recovery"?"管理后台服务、局部移除和完整恢复":key=="messages"?"设置正文、辅助文字与链接颜色":"修改后点击右下角应用 · 支持运行时更新";workspaceApply.Text=key=="palette"?"应用基础配色":key=="wallpaper"?"应用壁纸设置":"应用本页设置";workspaceApply.Enabled=key!="recovery"&&key!="deployment";workspaceApply.Visible=key!="recovery"&&key!="deployment";workspaceBody.ResumeLayout();}
